def U_of(k):
    """The universe: 10 templates, 22-23 concrete rules for a roll of k dice."""
    return ([(0, n) for n in (3*k-2, 3*k, 3*k+2, 3*k+4)]          # total is exactly n
        + [(1, 4*k+2), (2, 3*k-2), (9, 0)]                        # total > n ; total < n ; biggest = 2*smallest
        + [(3, m) for m in (3, 4)]                                # biggest die is m
        + [(4, m) for m in (3, 4)]                                # smallest die is m
        + [(5, v) for v in range(1, 7)]                           # exactly two dice show v
        + [(6, i) for i in range(1, min(k-1, 3))]                 # exactly i different numbers
        + [(7, s) for s in (k+3, k+4)]                            # two biggest add up to s
        + [(8, s) for s in (10-k, 11-k)])                         # two smallest add up to s

def P(r, d):
    """d is a SORTED tuple of k pips."""
    t, q = r
    S = sum(d)
    return [S == q, S > q, S < q, d[-1] == q, d[0] == q, d.count(q) == 2,
            len(set(d)) == q, d[-1]+d[-2] == q, d[0]+d[1] == q, d[-1] == 2*d[0]][t]

CACHE = {}

def tables(k):
    if k in CACHE:
        return CACHE[k]
    U = U_of(k)
    M = list(itertools.combinations_with_replacement(range(1, 7), k))
    masks = []
    for d in M:
        b = 0
        for j, r in enumerate(U):
            if P(r, d):
                b |= 1 << j
        masks.append(b)
    sat = [[i for i, b in enumerate(masks) if b >> j & 1] for j in range(len(U))]
    CACHE[k] = (U, M, masks, sat)
    return CACHE[k]

def generate(seed):
    r = random.Random(seed)
    for _ in range(400):
        k = r.choice((3, 4, 4, 5, 5))
        U, M, masks, sat = tables(k)
        j = r.randrange(len(U))
        A = sat[j]
        if len(A) < 5:
            continue
        best = None
        # prefer a MINIMAL identifying set of 3 examples: the three together leave
        # exactly one rule of U alive, and no two of them do
        for _t in range(40):
            T = r.sample(A, 3)
            if (masks[T[0]] & masks[T[1]] & masks[T[2]]).bit_count() != 1:
                continue
            if (masks[T[0]] & masks[T[1]]).bit_count() == 1:
                continue
            if (masks[T[0]] & masks[T[2]]).bit_count() == 1:
                continue
            if (masks[T[1]] & masks[T[2]]).bit_count() == 1:
                continue
            best = T
            break
        if best is None:                       # else a minimal pair
            for _t in range(40):
                T = r.sample(A, 2)
                if (masks[T[0]] & masks[T[1]]).bit_count() == 1 and masks[T[0]].bit_count() > 1 and masks[T[1]].bit_count() > 1:
                    best = T
                    break
        if best is None or len(A) < len(best) + 2:
            continue
        lines = []
        for i in best:
            d = list(M[i])
            r.shuffle(d)
            lines.append(" ".join(map(str, d)))
        return "\n".join(lines)
    return "1 1 2\n2 2 1"

